css:
@page {
  size: A4;
  margin: 10mm;
}

body {
  font-family: Arial, sans-serif;
  font-size: 11px;
}

table {
  width: 100%;
  border-collapse: collapse;
}

td, th {
  border: 1px solid #000;
  padding: 5px;
  vertical-align: top;
}


.header td {
  border: none;
}

.logo img {
  height: 45px;
}

.head-center {
  text-align: center;
}

.red-line {
  height: 3px;
  background: red;
  margin-top: 4px;
}

.head-right {
  width: 32%;
  text-align: right;
  vertical-align: top;
  padding-top: 0;
}

.track {
  width: 85%;         
  margin-left: auto;  
  margin-top: -6px;   
  font-size: 10px;
  border-collapse: collapse;
}


.track td {
  border: 1px solid #000;
  padding: 2px 4px;
}


.track td + td {
  border-left: none;
}

.title {
  text-align: center;
  font-weight: bold;
  border: 1px solid #000;
  padding: 6px;
  margin: 6px 0;
}

.main {
  margin-bottom: 6px;
}

.blue {
  background: #2f75b5;
  color: #fff;
  font-weight: bold;
  text-align: center;
}


.desc-text {
  margin-bottom: 6px;
}

.inner {
  width: 100%;
  border-collapse: collapse;
}

.inner th,
.inner td {
  border: 1px solid #000;
  font-size: 10px;
  padding: 4px;
  text-align: center;
}

.pay {
  margin-top: 6px;
}

.footer {
  text-align: center;
  font-size: 10px;
  margin-top: 8px;
}
.remark-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}

.remark-table td {
  padding: 6px;
  border-bottom: 1px solid #000; 
}

.remark-table tr:last-child td {
  border-bottom: none;
}

.collect-text {
  font-weight: bold;
  text-transform: uppercase;
}
